import 'package:flutter/material.dart';import '../services/security_service.dart';
class LockScreen extends StatefulWidget{final Widget child;const LockScreen({super.key,required this.child});@override State<LockScreen> createState()=>_S();}
class _S extends State<LockScreen>{final sec=SecurityService(),pin=TextEditingController();bool unlocked=false,loading=true;@override void initState(){super.initState();_start();}Future<void>_start()async{if(!await sec.hasPin()){setState(()=>unlocked=true);return;}if(await sec.biometricEnabled()&&await sec.authenticate()){setState(()=>unlocked=true);return;}setState(()=>loading=false);} @override Widget build(BuildContext c){if(unlocked)return widget.child;if(loading)return const Scaffold(body:Center(child:CircularProgressIndicator()));return Scaffold(body:SafeArea(child:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:360),child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.lock_outline,size:54),const SizedBox(height:16),Text('SaldoCerto',style:Theme.of(c).textTheme.headlineSmall),const SizedBox(height:24),TextField(controller:pin,obscureText:true,keyboardType:TextInputType.number,onSubmitted:(_)=>_unlock(),decoration:const InputDecoration(labelText:'PIN')),const SizedBox(height:12),FilledButton(onPressed:_unlock,child:const Text('Entrar')),TextButton.icon(onPressed:()async{if(await sec.authenticate())setState(()=>unlocked=true);},icon:const Icon(Icons.fingerprint),label:const Text('Usar biometria'))]))))));}Future<void>_unlock()async{if(await sec.checkPin(pin.text)){setState(()=>unlocked=true);}else if(mounted){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('PIN incorreto.')));}}}
